async function showPreview(container){const requested=++previewSequence;const loading=el('p','Preparing preview…','hint');container.replaceChildren(loading);try{const result=await api('listing_preview',{...d,id:record?.id||0});if(requested!==previewSequence||!container.isConnected)return;feedback.textContent='';container.replaceChildren();if(previewTab==='map'){container.append(el('h3','Google Maps Preview'),el('p',d.business_name||d.name),el('p',d.address||'Address not added','hint'));if(result.embed_url){const status=el('p','Loading Google Maps frame…','map-load-status');status.setAttribute('role','status');const frame=el('iframe',undefined,'map-preview-frame');frame.title='Google Maps Preview';frame.referrerPolicy='no-referrer-when-downgrade';frame.allowFullscreen=true;frame.src=result.embed_url;const timer=setTimeout(()=>{if(status.isConnected)status.textContent='Google Maps has not confirmed a visible map. Check your connection, browser privacy settings, or the embed code.'},12000);frame.onload=()=>{clearTimeout(timer);status.textContent='Frame navigation finished. Verify the business on the visible map; your browser may block Google content.'};frame.onerror=()=>{clearTimeout(timer);status.textContent='Google Maps could not load. Check your connection and use a fresh Share → Embed a map code.'};container.append(status,frame,el('p','This publishes Google’s official map. It does not import individual reviews.','hint'))}else container.append(el('div','Add an official Share → Embed a map code to see the map here.','empty-state'));if(d.maps_url)container.append(external('View on Google Maps',d.maps_url));if(d.reviews_url)container.append(external('View Google Reviews',d.reviews_url));container.append(button('Edit Embed',()=>{step=2;draw();body.querySelector('[name=embed_url]').focus()},true))}else{container.append(el('h3','Reviews Preview'));if(!result.review_count){container.append(el('div',Number(result.saved_count)>0?'No published reviews are available for this location.':'No reviews have been imported for this location.','empty-state'),el('p','A public Google Maps embed does not grant access to individual reviews for a custom carousel.','hint'));const links=el('div',undefined,'toolbar');const a=el('a','Import Reviews','button');a.href='admin.php?page=grw-reviews';links.append(a,button('Configure Authorized Review Source',()=>{step=3;draw()},true));if(d.reviews_url)links.append(external('View Reviews on Google',d.reviews_url));container.append(links)}else{const frame=el('iframe',undefined,'reviews-preview-frame');frame.title='Authorized Reviews Preview';frame.srcdoc='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="'+result.css+'"><style>body{margin:0;font-family:system-ui}</style></head><body>'+result.reviews_html+'<script src="'+result.js+'"></script></body></html>';container.append(frame)}}}catch(e){if(requested===previewSequence){container.replaceChildren(el('p',e.message,'preview-error'));validation(e)}}}
